// Detecta a que periodo (anio + rango de semanas epidemiologicas) se
// refiere la pregunta del analista, SIN usar ningun modelo de IA (cero
// tokens gastados aqui). Gemini sigue siendo el unico que interpreta
// la pregunta completa y redacta la respuesta - este nodo solo decide
// que filas de boletines_descubiertos / clima_alineado traer.
//
// Reconoce:
//   - "semana 15", "SE 27" -> 1 semana especifica
//   - "mayo 2025", "julio de 2026" -> todas las semanas de ese mes
//   - "entre marzo y mayo de 2025" -> rango de semanas entre esos 2 meses
//   - nada reconocido -> ventana por defecto: ultimas 12 semanas
//     respecto a la semana mas reciente que ya tenga resumen

const pregunta = ($('Webhook').item.json.body.pregunta || '').toLowerCase();

const MESES = {
  'enero': 1, 'febrero': 2, 'marzo': 3, 'abril': 4, 'mayo': 5, 'junio': 6,
  'julio': 7, 'agosto': 8, 'septiembre': 9, 'setiembre': 9, 'octubre': 10,
  'noviembre': 11, 'diciembre': 12
};

function getSemanaEpi(fechaStr) {
  // DGE: semana domingo-sabado; SE 01 = la que contiene el 4 de enero
  const fecha = new Date(fechaStr);
  const dom = new Date(Date.UTC(fecha.getUTCFullYear(), fecha.getUTCMonth(), fecha.getUTCDate()));
  dom.setUTCDate(dom.getUTCDate() - dom.getUTCDay());
  const mie = new Date(dom);
  mie.setUTCDate(dom.getUTCDate() + 3);
  const anio = mie.getUTCFullYear();
  const jan4 = new Date(Date.UTC(anio, 0, 4));
  const domSE1 = new Date(jan4);
  domSE1.setUTCDate(jan4.getUTCDate() - jan4.getUTCDay());
  const semana = Math.round((dom - domSE1) / (7 * 86400000)) + 1;
  return { anio, semana };
}

function rangoSemanasDeMes(anio, mes) {
  const primerDia = new Date(Date.UTC(anio, mes - 1, 1));
  const ultimoDia = new Date(Date.UTC(anio, mes, 0));
  const inicio = getSemanaEpi(primerDia.toISOString());
  const fin = getSemanaEpi(ultimoDia.toISOString());
  return { anio: inicio.anio, semanaInicio: inicio.semana, semanaFin: fin.semana };
}

// --- 1. Intentar detectar RANGO "entre <mes1> y <mes2> de <anio>" ---
const regexRango = new RegExp(
  `entre\\s+(${Object.keys(MESES).join('|')})\\s+y\\s+(${Object.keys(MESES).join('|')})\\s+(?:de\\s+)?(\\d{4})`,
  'i'
);
const matchRango = pregunta.match(regexRango);

if (matchRango) {
  const [, mes1Str, mes2Str, anioStr] = matchRango;
  const anio = Number(anioStr);
  const mes1 = MESES[mes1Str];
  const mes2 = MESES[mes2Str];

  const r1 = rangoSemanasDeMes(anio, mes1);
  const r2 = rangoSemanasDeMes(anio, mes2);

  return [{
    json: {
      anio,
      semana_desde: Math.min(r1.semanaInicio, r2.semanaInicio),
      semana_hasta: Math.max(r1.semanaFin, r2.semanaFin),
      criterio_usado: `rango: ${mes1Str} a ${mes2Str} ${anio}`
    }
  }];
}

// --- 2. Intentar detectar "SEMANA N" o "SE N" explicita ---
const regexSemana = /(?:semana|se)\s*(\d{1,2})(?:\s*-?\s*(\d{4}))?/i;
const matchSemana = pregunta.match(regexSemana);

if (matchSemana) {
  const semana = Number(matchSemana[1]);
  const anio = matchSemana[2] ? Number(matchSemana[2]) : new Date().getFullYear();

  return [{
    json: {
      anio,
      semana_desde: semana,
      semana_hasta: semana,
      criterio_usado: `semana especifica: SE ${semana}-${anio}`
    }
  }];
}

// --- 3. Intentar detectar "<mes> de <anio>" o "<mes> <anio>" ---
const regexMes = new RegExp(`(${Object.keys(MESES).join('|')})\\s+(?:de\\s+)?(\\d{4})`, 'i');
const matchMes = pregunta.match(regexMes);

if (matchMes) {
  const [, mesStr, anioStr] = matchMes;
  const anio = Number(anioStr);
  const mes = MESES[mesStr];
  const r = rangoSemanasDeMes(anio, mes);

  return [{
    json: {
      anio,
      semana_desde: r.semanaInicio,
      semana_hasta: r.semanaFin,
      criterio_usado: `mes especifico: ${mesStr} ${anio}`
    }
  }];
}


// --- 3.5 Intentar detectar SOLO "el anio <AAAA>" o "<AAAA>" suelto
//     (sin mes), ej. "en el año 2023", "durante 2023", "en 2023",
//     "para 2023", "de 2023", "del 2023". Se ampliaron los
//     conectores porque la version anterior exigia "en el año" /
//     "año" pegado al numero, y no reconocia el caso mas comun de
//     "en <AAAA>" suelto (ej. "cuantos casos hubo en 2023") - eso
//     hacia que la pregunta cayera al fallback de "ultimas 12
//     semanas" en vez de al anio correcto. ---
const regexAnioSolo = /\b(?:en el a[nñ]o|durante(?:\s+el)?(?:\s+a[nñ]o)?|del a[nñ]o|a[nñ]o|en|para|de|del)\s+(\d{4})\b/i;
const matchAnioSolo = pregunta.match(regexAnioSolo);

if (matchAnioSolo) {
  const anio = Number(matchAnioSolo[1]);
  return [{
    json: {
      anio,
      semana_desde: 1,
      semana_hasta: 53,
      criterio_usado: `anio completo: ${anio}`
    }
  }];
}

// --- 3.6 Ultimo recurso antes del fallback: CUALQUIER año de 4
//     digitos suelto en la pregunta (2010-2029), sin conector
//     reconocido antes (ej. "dengue Loreto 2023", "boletin 2026").
//     Si esto tampoco matchea, recien ahi se usa la ventana de las
//     ultimas 12 semanas. Evita que preguntas con año explicito pero
//     redaccion poco comun caigan silenciosamente al default. ---
const regexAnioSuelto = /\b(20[1-2]\d)\b/;
const matchAnioSuelto = pregunta.match(regexAnioSuelto);

if (matchAnioSuelto) {
  const anio = Number(matchAnioSuelto[1]);
  return [{
    json: {
      anio,
      semana_desde: 1,
      semana_hasta: 53,
      criterio_usado: `anio completo (deteccion generica): ${anio}`
    }
  }];
}

// --- 4. Nada detectado: ventana por defecto (ultimas 12 semanas) ---
return [{
  json: {
    anio: null,
    semana_desde: null,
    semana_hasta: null,
    ventana_por_defecto: 12,
    criterio_usado: 'sin periodo detectado: se usara ventana de las ultimas 12 semanas'
  }
}];

// Si 'Detectar periodo en la pregunta' no encontro nada explicito
// (ventana_por_defecto viene seteada), se calcula la ventana de las
// ultimas 12 semanas tomando como referencia la semana mas reciente
// que YA tenga resumen generado (no la fecha de hoy, para no traer
// semanas que ni siquiera han sido procesadas todavia por Fase B).

const deteccion = $('Detectar periodo en la pregunta').first().json;

function esNulo(valor) {
  return valor === null || valor === undefined || valor === 'null' || valor === '';
}

if (!esNulo(deteccion.anio)) {
  // Ya se detecto un periodo explicito, se pasa tal cual.
  return [{ json: deteccion }];
}

const todasLasFilas = $input.all().map(i => i.json);
function tieneResumenReal(resumen) {
  if (!resumen) return false;
  const texto = resumen.toString().trim().toLowerCase();
  if (texto.length === 0) return false;
  if (texto === 'empty' || texto === 'null' || texto === 'undefined') return false;
  return true;
}

const conResumen = todasLasFilas.filter(f => tieneResumenReal(f.resumen));

if (conResumen.length === 0) {
  throw new Error('No hay ningun boletin con resumen generado todavia en boletines_descubiertos.');
}

const masReciente = conResumen.reduce((max, f) => {
  if (f.anio > max.anio) return f;
  if (f.anio === max.anio && f.semana_epidemiologica > max.semana_epidemiologica) return f;
  return max;
}, conResumen[0]);

const N = deteccion.ventana_por_defecto || 12;

// Genera la lista de (anio, semana) de las ultimas N semanas contando
// hacia atras desde la mas reciente, manejando el cruce de anio (ej.
// semana 3 del 2026 menos 12 cae en el 2025).
let anio = masReciente.anio;
let semana = masReciente.semana_epidemiologica;
const semanasDelAnioAnterior = 52; // aproximacion suficiente para acotar la ventana

let semanaDesdeAnio = anio;
let semanaDesde = semana - (N - 1);
if (semanaDesde < 1) {
  semanaDesdeAnio = anio - 1;
  semanaDesde = semanasDelAnioAnterior + semanaDesde;
}

return [{
  json: {
    anio: null, // se usa rango multi-anio explicito en vez de un solo anio
    semana_desde: semanaDesde,
    semana_hasta: semana,
    anio_desde: semanaDesdeAnio,
    anio_hasta: anio,
    criterio_usado: `ventana por defecto: ultimas ${N} semanas hasta SE ${semana}-${anio}`
  }
}];

function tieneResumenReal(resumen) {
  if (!resumen) return false;
  const texto = resumen.toString().trim().toLowerCase();
  if (texto.length === 0) return false;
  if (texto === 'empty' || texto === 'null' || texto === 'undefined') return false;
  return true;
}

const periodo = $('Resolver ventana por defecto (si aplica)').first().json;
const todasLasFilas = $('Get row(s)1').all().map(i => i.json);

const filasConResumen = todasLasFilas.filter(function(f) {
  return tieneResumenReal(f.resumen);
});

const anioEspecifico = periodo.anio;
const hayPeriodoEspecifico = (anioEspecifico !== null && anioEspecifico !== undefined && anioEspecifico !== 'null');

let filtradas = [];

if (hayPeriodoEspecifico) {
  const anioNum = parseInt(anioEspecifico, 10);

  // Si el anio pedido es anterior a 2025, los boletines NUNCA van a
  // tener ese periodo (solo cubren 2025 en adelante) - esto no es un
  // error, es esperado: ese periodo se resuelve por Postgres
  // (prediccion), no por boletines. No se lanza error aqui; se
  // devuelve vacio silenciosamente y el AI Agent solo recibira la
  // tendencia de Postgres, sin bloquear el flujo completo.
  if (anioNum < 2025) {
    return [{ json: { _sin_boletines: true } }];
  }

  const semanaDesde = parseInt(periodo.semana_desde, 10);
  const semanaHasta = parseInt(periodo.semana_hasta, 10);

  filtradas = filasConResumen.filter(function(f) {
    const anioFila = parseInt(f.anio, 10);
    const semanaFila = parseInt(f.semana_epidemiologica, 10);
    return anioFila === anioNum && semanaFila >= semanaDesde && semanaFila <= semanaHasta;
  });

  if (filtradas.length === 0) {
    throw new Error('No se encontraron boletines con resumen para el periodo solicitado: ' + periodo.criterio_usado);
  }
} else {
  const anioDesde = parseInt(periodo.anio_desde, 10);
  const anioHasta = parseInt(periodo.anio_hasta, 10);
  const semanaDesde = parseInt(periodo.semana_desde, 10);
  const semanaHasta = parseInt(periodo.semana_hasta, 10);

  const claveDesde = anioDesde * 100 + semanaDesde;
  const claveHasta = anioHasta * 100 + semanaHasta;

  filtradas = filasConResumen.filter(function(f) {
    const anioFila = parseInt(f.anio, 10);
    const semanaFila = parseInt(f.semana_epidemiologica, 10);
    const claveFila = anioFila * 100 + semanaFila;
    return claveFila >= claveDesde && claveFila <= claveHasta;
  });

  if (filtradas.length === 0) {
    filtradas = filasConResumen;
  }
}

if (filtradas.length === 0) {
  return [{ json: { _sin_boletines: true } }];
}

return filtradas.map(function(f) {
  return { json: f };
});

const periodo = $('Resolver ventana por defecto (si aplica)').first().json;
const filas = $('Get row(s)').all().map(i => i.json);

const anioEspecifico = periodo.anio;
const hayPeriodoEspecifico = (anioEspecifico !== null && anioEspecifico !== undefined && anioEspecifico !== 'null');

let filtradas = [];

if (hayPeriodoEspecifico) {
  const anioNum = parseInt(anioEspecifico, 10);
  const semanaDesde = parseInt(periodo.semana_desde, 10);
  const semanaHasta = parseInt(periodo.semana_hasta, 10);

  filtradas = filas.filter(function(f) {
    const anioFila = parseInt(f.anio, 10);
    const semanaFila = parseInt(f.semana_epidemiologica, 10);
    return anioFila === anioNum && semanaFila >= semanaDesde && semanaFila <= semanaHasta;
  });
} else {
  const anioDesde = parseInt(periodo.anio_desde, 10);
  const anioHasta = parseInt(periodo.anio_hasta, 10);
  const semanaDesde = parseInt(periodo.semana_desde, 10);
  const semanaHasta = parseInt(periodo.semana_hasta, 10);

  const claveDesde = anioDesde * 100 + semanaDesde;
  const claveHasta = anioHasta * 100 + semanaHasta;

  filtradas = filas.filter(function(f) {
    const anioFila = parseInt(f.anio, 10);
    const semanaFila = parseInt(f.semana_epidemiologica, 10);
    const claveFila = anioFila * 100 + semanaFila;
    return claveFila >= claveDesde && claveFila <= claveHasta;
  });
}

return filtradas.map(function(f) {
  return { json: f };
});

// Arma un unico bloque de texto con todos los boletines del periodo
// (resumen completo por cada semana) y un resumen compacto del clima
// promedio nacional por semana (promediando los 25 departamentos, para
// no inflar el prompt con 25 filas de clima por cada semana). Este
// texto consolidado es lo que recibe el AI Agent.

const boletines = $('Filtrar boletines del periodo').all().map(i => i.json).filter(b => !b._sin_boletines);
const clima = $('Filtrar clima del periodo').all().map(i => i.json);
const periodo = $('Resolver ventana por defecto (si aplica)').first().json;

const boletinesOrdenados = boletines.sort((a, b) => {
  if (a.anio !== b.anio) return a.anio - b.anio;
  return a.semana_epidemiologica - b.semana_epidemiologica;
});

let textoBoletines = '';
for (const b of boletinesOrdenados) {
  textoBoletines += `\n--- Boletin SE ${b.semana_epidemiologica}-${b.anio} ---\n${b.resumen}\n`;
}

// Promedio nacional de clima por semana (agrupando los 25 departamentos)
const climaPorSemana = {};
for (const c of clima) {
  const key = `${c.anio}-${c.semana_epidemiologica}`;
  if (!climaPorSemana[key]) {
    climaPorSemana[key] = { anio: c.anio, semana: c.semana_epidemiologica, temp_max: [], temp_min: [], precipitacion: [] };
  }
  climaPorSemana[key].temp_max.push(c.temp_max_promedio);
  climaPorSemana[key].temp_min.push(c.temp_min_promedio);
  climaPorSemana[key].precipitacion.push(c.precipitacion_total);
}

const promedio = arr => (arr.reduce((a, b) => a + b, 0) / arr.length).toFixed(1);

let textoClima = '';
const semanasClima = Object.values(climaPorSemana).sort((a, b) => (a.anio - b.anio) || (a.semana - b.semana));
for (const s of semanasClima) {
  textoClima += `SE ${s.semana}-${s.anio}: temp. max promedio nacional ${promedio(s.temp_max)}°C, temp. min promedio ${promedio(s.temp_min)}°C, precipitacion promedio ${promedio(s.precipitacion)}mm\n`;
}

const textoTendencia = (() => {
  try {
    return $('Armar texto de tendencia').first().json.texto_tendencia || '';
  } catch (e) {
    return '';
  }
})();

return [{
  json: {
    texto_boletines: textoBoletines.trim(),
    texto_tendencia: textoTendencia,
    texto_clima: textoClima.trim(),
    criterio_periodo: periodo.criterio_usado,
    cantidad_boletines: boletinesOrdenados.length
  }
}];

// Detecta si la pregunta menciona un departamento peruano, para
// activar (o no) la rama de prediccion de tendencia via Postgres.
// Sin costo de tokens de IA, mismo estilo que 'Detectar periodo'.

const departamentos = {
  'amazonas': '01', 'ancash': '02', 'apurimac': '03', 'arequipa': '04',
  'ayacucho': '05', 'cajamarca': '06', 'callao': '07', 'cusco': '08',
  'huancavelica': '09', 'huanuco': '10', 'ica': '11', 'junin': '12',
  'la libertad': '13', 'lambayeque': '14', 'lima': '15', 'loreto': '16',
  'madre de dios': '17', 'moquegua': '18', 'pasco': '19', 'piura': '20',
  'puno': '21', 'san martin': '22', 'tacna': '23', 'tumbes': '24', 'ucayali': '25'
};

const pregunta = ($('Webhook').item.json.body.pregunta || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

let departamentoDetectado = null;
let codigoDetectado = null;

for (const [nombre, codigo] of Object.entries(departamentos)) {
  const nombreSinTildes = nombre.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (pregunta.includes(nombreSinTildes)) {
    departamentoDetectado = nombre;
    codigoDetectado = codigo;
    break;
  }
}

return [{
  json: {
    departamento_detectado: departamentoDetectado,
    codigo_departamento: codigoDetectado
  }
}];

// Decide si corresponde consultar Postgres (prediccion historica
// <=2024). Se activa si:
//   1. el periodo resuelto (de 'Resolver ventana por defecto') toca al
//      menos parcialmente anios <= 2024, INDEPENDIENTE de si hay
//      departamento o no.
//
// Si SI se detecto un departamento en la pregunta, la consulta se
// filtra a ese departamento especifico. Si NO se detecto ninguno
// (pregunta generica de enfermedad+anio, ej. "cuantos casos de EDA
// hubo en 2023"), se consulta a nivel NACIONAL (los 25 departamentos
// sumados) en vez de no responder nada - decision tomada explicitamente
// para no obligar al analista a nombrar un departamento cuando su
// pregunta es agregada a proposito.
//
// Si el periodo es exclusivamente 2025-2026, NO se consulta Postgres:
// esos anios no tienen datos de casos individuales todavia (se rellenan
// con los boletines, que el AI Agent ya recibe por otro lado).
//
// Ademas arrastra las banderas de que enfermedad(es) consultar
// (de 'Detectar enfermedad en la pregunta'), para que cada nodo
// Postgres de tendencia (dengue/eda/ira_neumonia/ira_no_neumonia)
// sepa si le corresponde ejecutarse.

const deteccionDepto = $('Detectar departamento en la pregunta').first().json;
const deteccionEnfermedad = $('Detectar enfermedad en la pregunta').first().json;
const periodo = $('Resolver ventana por defecto (si aplica)').first().json;

// Determinar si el rango de periodo toca anios <= 2024
let anioDesde, anioHasta;
const anioEspecifico = periodo.anio;
const hayPeriodoEspecifico = (anioEspecifico !== null && anioEspecifico !== undefined && anioEspecifico !== 'null');

if (hayPeriodoEspecifico) {
  anioDesde = parseInt(periodo.anio, 10);
  anioHasta = parseInt(periodo.anio, 10);
} else {
  anioDesde = parseInt(periodo.anio_desde, 10);
  anioHasta = parseInt(periodo.anio_hasta, 10);
}

const tocaHistorico = anioDesde <= 2024;

if (!tocaHistorico) {
  return [{ json: { activar_prediccion: false, motivo: 'el periodo solicitado es 2025 en adelante, cubierto por boletines, no por Postgres' } }];
}

// Se activa la prediccion. Se acota el rango a consultar en Postgres a
// como maximo el anio 2024 (si el rango pedido cruza a 2025+, esa parte
// ya la cubre el boletin por otro lado).
const anioHastaAcotado = Math.min(anioHasta, 2024);

// codigo_departamento puede venir null -> las queries Postgres estan
// preparadas para tratarlo como "sin filtro de departamento" (agregado
// nacional, sumando los 25).
const hayDepartamento = !!deteccionDepto.codigo_departamento;

return [{
  json: {
    activar_prediccion: true,
    codigo_departamento: deteccionDepto.codigo_departamento || null,
    departamento_detectado: deteccionDepto.departamento_detectado || null,
    nivel_agregacion: hayDepartamento ? 'departamento' : 'nacional',
    anio_desde: anioDesde,
    anio_hasta: anioHastaAcotado,
    semana_desde: hayPeriodoEspecifico ? parseInt(periodo.semana_desde, 10) : parseInt(periodo.semana_desde, 10),
    semana_hasta: hayPeriodoEspecifico ? parseInt(periodo.semana_hasta, 10) : 53,
    incluir_dengue: deteccionEnfermedad.incluir_dengue,
    incluir_eda: deteccionEnfermedad.incluir_eda,
    incluir_ira_neumonia: deteccionEnfermedad.incluir_ira_neumonia,
    incluir_ira_no_neumonia: deteccionEnfermedad.incluir_ira_no_neumonia,
    enfermedades_activas: deteccionEnfermedad.enfermedades_activas
  }
}];

// Consolida hasta 4 fuentes de tendencia historica (Dengue, EDA,
// IRA neumonia, IRA no neumonia) en un solo texto para el prompt.
// Recibe todos los items ya juntos desde 'Merge (tendencias por
// enfermedad)' (modo append: cada Postgres aporta sus filas, ya
// filtradas por su propio flag incluir_X dentro del WHERE - las
// enfermedades no activas simplemente no aportan filas).
//
// Soporta 2 niveles de agregacion (decision.nivel_agregacion):
//   - 'departamento': el analista menciono un departamento especifico,
//     las queries ya vinieron filtradas a ese departamento.
//   - 'nacional': no se detecto departamento en la pregunta, las
//     queries ya vinieron sumando/promediando los 25 departamentos.
//
// IRA neumonia + no neumonia se combinan en una sola seccion "IRA"
// cuando ambas vinieron activas (caso por defecto); si solo vino
// una (ej. el analista pidio "neumonia" especificamente), se
// muestra solo esa, ya etiquetada como tal.
//
// Si no hay prediccion activada en absoluto (periodo fuera de
// 2010-2024), llega directo desde la rama FALSE de 'Hay prediccion
// que consultar?', sin pasar por Postgres ni por el Merge: texto
// vacio. El AI Agent ya esta instruido para no inventar una
// prediccion si no recibe este dato.

const decision = $('Decidir si activar prediccion (Postgres)').first().json;

if (decision.activar_prediccion === false) {
  return [{ json: { texto_tendencia: '' } }];
}

const todasLasFilas = $input.all().map(i => i.json);

const filasDengue = todasLasFilas.filter(f => f.enfermedad === 'dengue');
const filasEda = todasLasFilas.filter(f => f.enfermedad === 'eda');
const filasIraNeu = todasLasFilas.filter(f => f.enfermedad === 'ira_neumonia');
const filasIraNoNeu = todasLasFilas.filter(f => f.enfermedad === 'ira_no_neumonia');

const esNacional = decision.nivel_agregacion === 'nacional';
const ambitoTexto = esNacional
  ? 'a nivel nacional (suma de los 25 departamentos, ya que la pregunta no menciono un departamento especifico)'
  : `en ${decision.departamento_detectado}`;

const climaTextoDe = (f) => (f.temp_max_promedio !== null && f.temp_max_promedio !== undefined)
  ? ` | clima ${esNacional ? 'promedio nacional' : ''}: temp max ${Number(f.temp_max_promedio).toFixed(1)}°C, temp min ${Number(f.temp_min_promedio).toFixed(1)}°C, precipitacion ${Number(f.precipitacion_total).toFixed(1)}mm, humedad ${Number(f.humedad_promedio).toFixed(1)}%`
  : ' | clima: sin dato disponible para esa semana';

function bloqueTexto(titulo, filas) {
  if (filas.length === 0) {
    return `${titulo} ${ambitoTexto}: no se encontraron casos historicos registrados en el periodo consultado (hasta 2024).\n`;
  }
  let texto = `${titulo} ${ambitoTexto} (datos oficiales hasta 2024):\n`;
  for (const f of filas) {
    texto += `SE ${f.semana}-${f.anio}: ${f.total_casos} casos${climaTextoDe(f)}\n`;
  }
  return texto;
}

const bloques = [];

if (decision.incluir_dengue) {
  bloques.push(bloqueTexto('Tendencia historica de casos de Dengue', filasDengue));
}

if (decision.incluir_eda) {
  bloques.push(bloqueTexto('Tendencia historica de casos de EDA (enfermedad diarreica aguda)', filasEda));
}

// IRA: si ambas sub-fuentes estan activas, se combinan sumando por
// semana en una sola seccion "IRA" (neumonia + no neumonia). Si solo
// una esta activa, se muestra por separado con su etiqueta especifica.
if (decision.incluir_ira_neumonia && decision.incluir_ira_no_neumonia) {
  const combinado = {};
  for (const f of [...filasIraNeu, ...filasIraNoNeu]) {
    const key = `${f.anio}-${f.semana}`;
    if (!combinado[key]) {
      combinado[key] = { anio: f.anio, semana: f.semana, total_casos: 0, temp_max_promedio: f.temp_max_promedio, temp_min_promedio: f.temp_min_promedio, precipitacion_total: f.precipitacion_total, humedad_promedio: f.humedad_promedio };
    }
    combinado[key].total_casos += Number(f.total_casos) || 0;
  }
  const filasCombinadas = Object.values(combinado).sort((a, b) => (a.anio - b.anio) || (a.semana - b.semana));
  bloques.push(bloqueTexto('Tendencia historica de casos de IRA (neumonia + no neumonia combinadas)', filasCombinadas));
} else if (decision.incluir_ira_neumonia) {
  bloques.push(bloqueTexto('Tendencia historica de casos de IRA - Neumonia (especifico, sin combinar con no-neumonia)', filasIraNeu));
} else if (decision.incluir_ira_no_neumonia) {
  bloques.push(bloqueTexto('Tendencia historica de casos de IRA - No neumonia (especifico)', filasIraNoNeu));
}

return [{ json: { texto_tendencia: bloques.join('\n').trim() } }];

// Detecta que enfermedad(es) pregunta el analista, por palabras clave,
// sin gastar tokens de IA. Mismo estilo que 'Detectar departamento'.
//
// Reglas acordadas:
//  - Si menciona "dengue" -> solo dengue.
//  - Si menciona "eda", "diarrea", "diarreica" -> solo EDA.
//  - Si menciona "neumonia" (con o sin tilde) -> solo IRA neumonia
//    (no se combina con no-neumonia en este caso, para permitir la
//    prediccion mas detallada que pidio el analista).
//  - Si menciona "ira" o "respiratoria"/"respiratorio" SIN decir
//    "neumonia" explicitamente -> IRA combinada (neumonia + no
//    neumonia sumadas).
//  - Si no se detecta NINGUNA palabra clave de enfermedad -> se activan
//    las 4 fuentes (dengue + eda + ira neumonia + ira no neumonia).
//    Consultar Postgres es barato (query agregada, milisegundos); el
//    costo real esta en tokens de IA, y el texto que llega al AI Agent
//    sigue siendo un resumen compacto sin importar cuantas fuentes se
//    consultaron.

const pregunta = ($('Webhook').item.json.body.pregunta || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const mencionaDengue = /dengue/.test(pregunta);
const mencionaEda = /\beda\b|diarrea|diarreic/.test(pregunta);
const mencionaNeumonia = /neumonia/.test(pregunta);
const mencionaIraGeneral = /\bira\b|respirator/.test(pregunta);

let incluirDengue = false;
let incluirEda = false;
let incluirIraNeumonia = false;
let incluirIraNoNeumonia = false;

const algunaDetectada = mencionaDengue || mencionaEda || mencionaNeumonia || mencionaIraGeneral;

if (!algunaDetectada) {
  // Nada detectado: se activan las 4 fuentes.
  incluirDengue = true;
  incluirEda = true;
  incluirIraNeumonia = true;
  incluirIraNoNeumonia = true;
} else {
  if (mencionaDengue) incluirDengue = true;
  if (mencionaEda) incluirEda = true;
  if (mencionaNeumonia) {
    // Pidio especificamente neumonia: no se combina con no-neumonia.
    incluirIraNeumonia = true;
  } else if (mencionaIraGeneral) {
    // IRA general (sin distinguir): combinada, ambas tablas.
    incluirIraNeumonia = true;
    incluirIraNoNeumonia = true;
  }
}

const enfermedadesActivas = [];
if (incluirDengue) enfermedadesActivas.push('dengue');
if (incluirEda) enfermedadesActivas.push('eda');
if (incluirIraNeumonia) enfermedadesActivas.push('ira_neumonia');
if (incluirIraNoNeumonia) enfermedadesActivas.push('ira_no_neumonia');

return [{
  json: {
    incluir_dengue: incluirDengue,
    incluir_eda: incluirEda,
    incluir_ira_neumonia: incluirIraNeumonia,
    incluir_ira_no_neumonia: incluirIraNoNeumonia,
    enfermedades_activas: enfermedadesActivas,
    criterio_enfermedad: algunaDetectada
      ? `detectadas: ${enfermedadesActivas.join(', ')}`
      : 'sin enfermedad especifica detectada: se consultan las 4'
  }
}];

// Extrae el marcador [NIVEL_RIESGO: alto|medio|bajo] que el AI Agent
// escribe al final de su respuesta (segun la instruccion agregada al
// prompt), lo separa a un campo 'nivel_riesgo' estructurado, y limpia
// esa linea del texto que ve el analista - para que no aparezca como
// texto crudo raro en el chat del frontend.
//
// Mismo principio que 'modelo_usado': un campo de transparencia
// aparte del texto libre, para que el frontend pueda mostrar un badge
// con certeza en vez de tener que adivinar buscando palabras clave
// dentro de la respuesta (fragil: la IA podria escribir "riesgo
// considerablemente alto" o negarlo, y un regex simple lo detectaria
// mal).

const salidaAgente = $input.first().json;
const textoOriginal = salidaAgente.output || '';

const regexMarcador = /\[NIVEL_RIESGO:\s*(alto|medio|bajo)\]/i;
const match = textoOriginal.match(regexMarcador);

const nivelRiesgo = match ? match[1].toLowerCase() : null;

// Quita la linea del marcador (y espacios en blanco sobrantes al final)
const textoLimpio = textoOriginal.replace(regexMarcador, '').trimEnd();

return [{
  json: {
    ...salidaAgente,
    output: textoLimpio,
    nivel_riesgo: nivelRiesgo
  }
}];
